#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

console.log('🔧 Setting up Frontend Production Environment...');

const envContent = `# Production Environment Variables
# Generated by setup-production-env.js

# API Base URL for production backend
VITE_API_URL=https://nutrigence.app/im-project-backend

# Other production-specific variables can be added here
`;

const envPath = path.join(__dirname, '.env.production');

try {
  fs.writeFileSync(envPath, envContent);
  console.log('✅ Production environment file created: .env.production');
  console.log('\n📝 Environment variables set:');
  console.log('   - VITE_API_URL=https://nutrigence.app/im-project-backend');
  console.log('\n🚀 Next steps:');
  console.log('   1. Deploy the frontend with this .env.production file');
  console.log('   2. Ensure the backend is accessible at the specified URL');
  console.log('   3. Test the API endpoints');
} catch (error) {
  console.error('❌ Error creating production environment file:', error);
  process.exit(1);
} 